func (e ListMySendsParamsState) Valid() bool {
	switch e {
	case ListMySendsParamsStateAll:
		return true
	case ListMySendsParamsStateDelivered:
		return true
	case ListMySendsParamsStateOngoing:
		return true
	default:
		return false
	}
}

